package dev.streamsreflowing.core.compose;
public final class ColumnPlan { private final boolean channel,corridor,source,terminal; private final int surface; private final double width,distance; public ColumnPlan(boolean channel,boolean corridor,int surface,double width,double distance,boolean source,boolean terminal){this.channel=channel;this.corridor=corridor;this.surface=surface;this.width=width;this.distance=distance;this.source=source;this.terminal=terminal;} public boolean inChannel(){return channel;} public boolean inCorridor(){return corridor;} public int waterSurfaceY(){return surface;} public double width(){return width;} public double distance(){return distance;} public boolean source(){return source;} public boolean terminal(){return terminal;} }